import * as T from 'three';import {person,captain,dressCaptain,box,sign} from './models.js';import {crewPosition,duty} from './crew.js';
export function stationLife(world){const group=new T.Group();world.add(group);box(group,44,.2,42,'#b7bba7',-70,.2,34);box(group,44,2,.4,'#bac7bf',-70,1,12);box(group,.4,2,42,'#bac7bf',-92,1,34);sign(group,'DORTOIR',12,1,-70,2.5,13);for(let i=0;i<19;i++){const x=-87+(i%6)*6,z=19+Math.floor(i/6)*5;box(group,2.1,.45,3.4,'#718886',x,.45,z);box(group,1.9,.16,3.2,'#b7c4b5',x,.75,z);box(group,1.7,.18,.75,'#e6e7d9',x,.9,z-1);}for(const [label,x]of[['SPORT',-85],['REPAS',-70],['RANGEMENT',-54]])sign(group,label,10,.7,x,1,53);for(let i=0;i<3;i++){box(group,8,.15,1.7,'#98754d',-69,1.05,40+i*3);box(group,8,.4,.4,'#60716a',-69,.6,41+i*3);box(group,1.3,2.5,1,'#6b7978',-54+i*2,1.5,39);}sign(group,'VSAV • ZONE HYGIÈNE',12,.7,-56,3,56.4,'#447d7e');sign(group,'ENGINS INCENDIE & APPUI',13,.7,-84,3,56.4,'#964539');const models=new Map();return{update(t,s,engines){for(const p of s.roster){if(!models.has(p.id))models.set(p.id,p.role==='captain'?captain(group,0,0,s.playerProfile):person(group,0,0,p.kind==='SPV'?'#74613c':'#334b65'));const m=models.get(p.id),e=engines.find(e=>e.id===p.engine);if(p.role==='captain')dressCaptain(m,s.playerProfile);m.visible=p.present&&!p.atResidence&&(!e||e.status==='departing'&&e.wasAtStation);if(!m.visible)continue;const task=duty(s.minute);m.rotation.set(0,0,0);let pos=crewPosition(p,s.minute),y=.3;if(e){const b=e.boarding?.find(b=>b.id===p.id);if(b){const elapsed=s.minute-e.alertAt;m.visible=elapsed<b.duration;const fraction=Math.max(0,Math.min(1,(elapsed-b.delay)/(b.duration-b.delay))),d1=Math.hypot(b.locker[0]-b.from[0],b.locker[1]-b.from[1]),d2=Math.hypot(e.home[0]-b.locker[0],e.home[1]-b.locker[1]),dist=fraction*(d1+d2),a=dist<d1?b.from:b.locker,z=dist<d1?b.locker:e.home,k=dist<d1?dist/d1:(dist-d1)/d2;pos=[a[0]+(z[0]-a[0])*k,a[1]+(z[1]-a[1])*k];m.rotation.y=Math.atan2(z[0]-a[0],z[1]-a[1]);}}else if(task==='dormitory'){m.rotation.x=-Math.PI/2;y=1.1;}else if(!['meal','breakfast','rest'].includes(task)){pos=[pos[0]+Math.sin(t*.6+p.id)*.6,pos[1]+Math.cos(t*.6+p.id)*.6];y+=task==='sport'?Math.abs(Math.sin(t*3+p.id))*.15:0;}m.position.set(pos[0],y,pos[1]);const moving=e||['sport','training','equipment'].includes(task);m.children[1].rotation.x=moving?Math.sin(t*5+p.id)*.3:0;m.children[2].rotation.x=moving?-Math.sin(t*5+p.id)*.3:0;}}};}
